int audio_beep(int freq_hz, int ms, int pa_gpio)
{
  const int fs = 16000;
  const int16_t amp = 8000;          /* ~ -12 dBFS, safe level */
  static int16_t period[320];        /* fs/50 = 320 max */
  int plen;
  long total;
  long i;

  if (freq_hz < 50)   freq_hz = 50;
  if (freq_hz > 4000) freq_hz = 4000;
  if (ms < 10)   ms = 10;
  if (ms > 5000) ms = 5000;

  plen = fs / freq_hz;
  if (plen < 4)   plen = 4;
  if (plen > 320) plen = 320;

