static uint8_t i2c_read_byte(bool ack)
{
  uint8_t b = 0;
  int i;

  sda_high();   /* release for slave to drive */
  for (i = 7; i >= 0; i--)
    {
      scl_high();                                  /* rising edge + settle */
      if (pin_read(ACCEL_SDA_PIN)) b |= (1u << i); /* sample while SCL high */
      scl_low();
    }

  if (ack) sda_low();
  else     sda_high();
  up_udelay(I2C_DELAY_US);
  scl_high();
  scl_low();
  sda_high();
  return b;
}

